func s2Less[T any](less func(a, b T) bool, x, y T) (T, T) {
	if less(y, x) {
		return y, x
	}
	return x, y
}

func heapSortLess[T any](a []T, less func(a, b T) bool) {
	n := len(a)
	if n < 2 {
		return
	}
	for i := n / 2; ; {
		var k T
		if i > 0 {
			i--
			k = a[i]
		} else {
			n--
			if n == 0 {
				return
			}
			k = a[n]
			a[n] = a[0]
		}
		j := i
		for j*2+1 < n {
			child := j*2 + 1
			if child+1 < n && (less(a[child], a[child+1])) {
				child++
			}
			if !(less(k, a[child])) {
				break
			}
			a[j] = a[child]
			j = child
		}
		a[j] = k
	}
}

